295	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
296	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
297	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
298	
299	    /**
300	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
301	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
302	     * upper-cased, and common street-type abbreviations are expanded token-by-token
303	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
304	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
305	     * used for every address comparison (household-duplicate detection and the shared household id).
306	     */
307	    private static String normalizeAddress(String value) {
308	        if (value == null) {
309	            return "";
310	        }
311	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
312	        if (collapsed.isEmpty()) {
313	            return "";
314	        }
315	        String[] tokens = collapsed.split(" ");
316	        StringBuilder sb = new StringBuilder();
317	        for (int i = 0; i < tokens.length; i++) {
318	            if (i > 0) {
319	                sb.append(' ');
320	            }
321	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
322	        }
323	        return sb.toString();
324	    }
