336	    /**
337	     * Builds the {@code customerCode} assigned to a new owner, formatted
338	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
339	     * owner's last name, and {@code NNNN} is a global 4-digit zero-padded sequence equal to
340	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
341	     */
342	    private String nextCustomerCode(String lastName) {
343	        String letters = lastName == null ? "" : lastName.replaceAll("[^\\p{L}]", "");
344	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
345	        long sequence = this.clinicService.findAllOwners().size() + 1L;
346	        return String.format("%s-%04d", last3, sequence);
347	    }
