349	    /**
350	     * Counts the existing owners that share the given first name and last name, compared
351	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
352	     * owner currently being created is saved), so it reflects how many namesakes preceded the
353	     * new owner.
354	     */
355	    private int countNamesakes(String firstName, String lastName) {
356	        return (int) this.clinicService.findAllOwners().stream()
357	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
358	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
359	            .count();
360	    }
