362	    /**
363	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
364	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
365	     * national one, a single leading {@code '0'} is dropped, and the default country code
366	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
367	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
368	     */
369	    private static String toE164(String telephone) {
370	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
371	        String digits;
372	        if (cleaned.startsWith("+")) {
373	            digits = cleaned.substring(1);
374	        } else {
375	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
376	            digits = "61" + national;
377	        }
378	        if (!digits.matches("[0-9]{8,15}")) {
379	            throw new InvalidTelephoneException(
380	                "telephone must form a valid E.164 number with 8 to 15 digits");
381	        }
382	        return "+" + digits;
383	    }
