387	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
388	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
389	     * stored and returned in canonical form.
390	     */
391	    private static String normalizeEmail(String email) {
392	        if (isBlank(email)) {
393	            return null;
394	        }
395	        String trimmed = email.trim();
396	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
397	            throw new InvalidEmailException("email must be a syntactically valid address");
398	        }
399	        return trimmed.toLowerCase(Locale.ROOT);
400	    }
